{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "과정 보상 모델 검토 결과",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "decision",
    "evidence",
    "risks",
    "actions"
  ],
  "properties": {
    "decision": {
      "type": "string",
      "minLength": 1
    },
    "evidence": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1
    },
    "risks": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "actions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1
    },
    "approved": {
      "type": "boolean",
      "default": false
    }
  }
}
